DROP TABLE IF EXISTS `FESTIVAL_I18N`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `FESTIVAL_I18N` (
  `IDX` bigint NOT NULL AUTO_INCREMENT,
