  CONSTRAINT `FK_NOTIFICATION_USERS` FOREIGN KEY (`USER_NO`) REFERENCES `USERS` (`NO`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
