DROP TABLE IF EXISTS `PLACE`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `PLACE` (
  `IDX` bigint NOT NULL AUTO_INCREMENT,
  `SOURCE` varchar(50) DEFAULT NULL,
  `CONTENT_ID` varchar(100) DEFAULT NULL,
  `TYPE` varchar(20) NOT NULL DEFAULT 'TOUR',
  `NAME` varchar(200) DEFAULT NULL,
  `TEXT` text,
  `CONTENT` text,
  `IMG` varchar(600) DEFAULT NULL,
  `ADDRESS` varchar(500) DEFAULT NULL,
  `LATITUDE` varchar(50) DEFAULT NULL,
  `LONGITUDE` varchar(50) DEFAULT NULL,
  `OPERATING_HOURS` varchar(300) DEFAULT NULL,
  `ADMISSION_FEE` varchar(300) DEFAULT NULL,
  `PARKING` varchar(300) DEFAULT NULL,
  `REST_DATE` varchar(300) DEFAULT NULL,
  `MENU` varchar(500) DEFAULT NULL,
  `CATEGORY_CODE` varchar(20) DEFAULT NULL,
  `CATEGORY_MAIN` varchar(50) DEFAULT NULL,
  `CATEGORY_SUB` varchar(50) DEFAULT NULL,
  `IS_DISPLAY` tinyint NOT NULL DEFAULT '1',
  `IS_RECOMMENDED` tinyint NOT NULL DEFAULT '0',
  `VIEW_COUNT` int NOT NULL DEFAULT '0',
  `REG_DATE` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `MODIFIED_TIME` datetime DEFAULT NULL COMMENT '공사 목록의 modifiedtime. 상세까지 받아 둔 회차에만 기록한다',
  PRIMARY KEY (`IDX`),
  UNIQUE KEY `UK_PLACE_SOURCE_CONTENT` (`SOURCE`,`CONTENT_ID`)
) ENGINE=InnoDB AUTO_INCREMENT=1856 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

