CREATE TABLE `PLACE_I18N` (
  `IDX` bigint NOT NULL AUTO_INCREMENT,
  `PLACE_IDX` bigint NOT NULL,
  `LANGUAGE_CODE` varchar(10) NOT NULL,
  `NAME` varchar(200) NOT NULL,
  `TEXT` text,
  `ADDRESS` varchar(500) DEFAULT NULL,
  `OPERATING_HOURS` varchar(300) DEFAULT NULL,
  `ADMISSION_FEE` varchar(300) DEFAULT NULL,
  `CREATED_AT` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `UPDATED_AT` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `MENU` varchar(500) DEFAULT NULL,
  `PARKING` varchar(300) DEFAULT NULL,
  `REST_DATE` varchar(300) DEFAULT NULL,
  `MODIFIED_TIME` datetime DEFAULT NULL,
  PRIMARY KEY (`IDX`),
  UNIQUE KEY `UK_PLACE_I18N` (`PLACE_IDX`,`LANGUAGE_CODE`),
  CONSTRAINT `FK_PLACE_I18N_PLACE` FOREIGN KEY (`PLACE_IDX`) REFERENCES `PLACE` (`IDX`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=14125 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
